/*
 * A041726  Numerators of continued fraction convergents to sqrt(383).
 * https://oeis.org/A041726
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(0) = 19 a(1) = 20 For n >= 2: a(n) = A_n * a(n-1) + a(n-2)
 *            where A_n is the n-th partial quotient in the continued fraction
 *            expansion of sqrt(383), generated by the standard recurrence
 *            with a0 = 19
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 31, u128 n <= 66,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Handle the trivial cases */
    if (n == 0) return (seq_t)19;
    /* Prepare the first two convergents */
    seq_t p_minus2 = (seq_t)1;          /* h_{-1} */
    seq_t p_minus1 = (seq_t)19;         /* h_0  */

    /* Continued‑fraction state for sqrt(383) */
    uint64_t m = 0;
    uint64_t d = 1;
    const uint64_t a0 = 19;
    uint64_t a = a0;                     /* a_0 */

    for (idx_t i = 1; i <= n; ++i) {
        /* Advance to the next partial quotient a_i */
        m = d * a - m;
        d = (383 - m * m) / d;
        a = (a0 + m) / d;

        /* Compute the next numerator of the convergent */
        seq_t p_cur = ((seq_t)a) * p_minus1 + p_minus2;
        /* Shift the sliding window */
        p_minus2 = p_minus1;
        p_minus1 = p_cur;
    }
    return p_minus1;
}
